        private static void GenDic汎用中間ファイル()
        {
            dic汎用中間ファイル.Clear();
            foreach (var item in 中間ファイル紐づけ情報list)
            {
                if (item.汎用中間ファイル.TableName != null)
                {
                    if (!dic汎用中間ファイル.ContainsKey(item.汎用中間ファイル.TableName))
                    {
                        dic汎用中間ファイル[item.汎用中間ファイル.TableName] = new();
                    }

                    dic汎用中間ファイル[item.汎用中間ファイル.TableName][item.汎用中間ファイル.ColumnName] = item;
                }
            }
        }
