        public static string GetPropertyValue(object entity, string propertyName)
        {
            // dbSetの型情報を取得
            Type entityType = entity.GetType();

            // 指定されたプロパティ名のプロパティ情報を取得
            PropertyInfo propertyInfo = entityType.GetProperty(propertyName) ?? throw new ArgumentException($"Property '{propertyName}' not found on '{entityType.FullName}'");

            // DbSetの値を取得
            // カラムが存在しない場合GetValueがnullを返す。その場合はひとまず空文字にする。
            var propValue = propertyInfo.GetValue(entity)?.ToString() ?? string.Empty;

            return propValue;
        }

        public static List<object> GetDbSet(DbContext context, string propertyName)
        {
            // nullチェック
            if (context == null)
                throw new ArgumentNullException(nameof(context));
            if (propertyName == null)
                throw new ArgumentNullException(nameof(propertyName));

            // DbContextの型情報を取得
            Type contextType = context.GetType();

            // 指定されたプロパティ名のプロパティ情報を取得
            PropertyInfo propertyInfo = contextType.GetProperty(propertyName);

            // プロパティが存在するか確認
            if (propertyInfo == null)
                throw new ArgumentException($"Property '{propertyName}' not found on '{contextType.FullName}'");

            // DbSetの値を取得
            var dbSet = propertyInfo.GetValue(context);

            // DbSetの型を取得
            Type entityType = propertyInfo.PropertyType.GetGenericArguments()[0];

            // DbSetをジェネリック型にキャストしてToList()を呼び出し、リストに変換
            var dbSetList = ((IEnumerable)dbSet).Cast<object>().ToList();

            return dbSetList;
        }

        public static bool CheckTableExists(DbContext context, string dbSetName)
        {
            //データベースにテーブルが存在するか確認
            bool IsExists = context.Database.SqlQuery<int?>(@$"SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = '{dbSetName}'").FirstOrDefault() > 0;
            return IsExists;
        }

